import{_ as i,a0 as u,w as a,s,I as p,x as r,a1 as e,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"Ubuntu NVIDIA 顯卡驅動 PPA 已經做好準備 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu NVIDIA 顯卡驅動 PPA 已經做好準備 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu NVIDIA 顯卡驅動 PPA 已經做好準備 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu NVIDIA 顯卡驅動 PPA 已經做好準備 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150816 Ubuntu NVIDIA Graphics Drivers PPA Is Ready For Action","title":"Ubuntu NVIDIA 顯卡驅動 PPA 已經做好準備","tag":"201508","desc":""},"relativePath":"201508/20150816 Ubuntu NVIDIA Graphics Drivers PPA Is Ready For Action.md","filePath":"[post].md"}'),l={name:"201508/20150816 Ubuntu NVIDIA Graphics Drivers PPA Is Ready For Action.md"};function P(A,t,I,b,m,g){const n=u("Link");return a(),s("div",null,[t[16]||(t[16]=p("h1",{id:"ubuntu-nvidia-顯卡驅動-ppa-已經做好準備",tabindex:"-1"},[r("Ubuntu NVIDIA 顯卡驅動 PPA 已經做好準備 "),p("a",{class:"header-anchor",href:"#ubuntu-nvidia-顯卡驅動-ppa-已經做好準備","aria-label":"Permalink to “Ubuntu NVIDIA 顯卡驅動 PPA 已經做好準備”"},"​")],-1)),t[17]||(t[17]=p("p",null,[p("img",{src:"http://www.omgubuntu.co.uk/wp-content/uploads/2015/08/Screen-Shot-2015-08-12-at-14.19.42.png",alt:""})],-1)),t[18]||(t[18]=p("p",null,"加速你的幀率！",-1)),t[19]||(t[19]=p("p",null,[p("strong",null,"嘿，各位，稍安勿躁，很快就好。")],-1)),p("p",null,[t[1]||(t[1]=r("就在提議開發一個",-1)),e(n,{href:"https://linux.cn/article-6030-1.html"},{default:o(()=>[...t[0]||(t[0]=[r("新的 PPA",-1)])]),_:1}),t[2]||(t[2]=r(" 來給 Ubuntu 用户們提供最新的 NVIDIA 顯卡驅動後不久，ubuntu 社區的人們又集結起來了，就是為了這件事。",-1))]),t[20]||(t[20]=d(`<p>顧名思義，‘<strong>Graphics Drivers PPA</strong>’ 包含了最新的 NVIDIA Linux 顯卡驅動發佈，已經打包好可供用户升級使用，沒有讓人頭疼的二進制運行時文件！</p><p>這個 PPA 被設計用來讓玩家們儘可能方便地在 Ubuntu 上運行最新款的遊戲。</p><h4 id="萬事俱備-只欠東風" tabindex="-1">萬事俱備，只欠東風 <a class="header-anchor" href="#萬事俱備-只欠東風" aria-label="Permalink to “萬事俱備，只欠東風”">​</a></h4><p>Jorge Castro 開發一個包含 NVIDIA 最新顯卡驅動的 PPA 神器的想法得到了 Ubuntu 用户和廣大遊戲開發者的熱烈響應。</p><p>就連那些致力於將“Steam平台”上的知名大作移植到 Linux 上的人們，也給了不少建議。</p><p>Edwin Smith，Feral Interactive 公司(‘Shadow of Mordor’) 的產品總監，對於“讓用户更方便地更新驅動”的倡議表示非常欣慰。</p><h3 id="如何使用最新的-nvidia-drivers-ppa" tabindex="-1">如何使用最新的 Nvidia Drivers PPA### <a class="header-anchor" href="#如何使用最新的-nvidia-drivers-ppa" aria-label="Permalink to “如何使用最新的 Nvidia Drivers PPA###”">​</a></h3><p>雖然新的“顯卡PPA”已經開發出來，但是現在還遠遠達不到成熟。開發者們提醒到：</p><blockquote><p>“這個 PPA 還處於測試階段，在你使用它之前最好有一些打包的經驗。請大家稍安勿躁，再等幾天。”</p></blockquote><p>將 PPA 試發佈給 Ubuntu desktop 郵件列表的 Jorge，也強調説，使用現行的一些 PPA（比如 xorg-edgers)的玩家可能發現不了什麼區別（因為現在的驅動只不過是把內容從其他那些現存驅動拷貝過來了）</p><p>“新驅動發佈的時候，好戲才會上演呢，”他説。</p><p>截至寫作本文時為止，這個 PPA 囊括了從 Ubuntu 12.04.1 到 15.10 各個版本的 Nvidia 驅動。注意這些驅動對所有的發行版都適用。</p><blockquote><p><strong>毫無疑問，除非你清楚自己在幹些什麼，並且知道如果出了問題應該怎麼撤銷，否則就不要進行下面的操作。</strong></p></blockquote><p>新打開一個終端窗口，運行下面的命令加入 PPA：</p><pre><code>sudo add-apt-repository ppa:graphics-drivers/ppa
</code></pre><p>安裝或更新到最新的 Nvidia 顯卡驅動：</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install nvidia-355
</code></pre><p>記住：如果PPA把你的系統弄崩了，你可得自己去想辦法，我們提醒過了哦。（譯者注：切記！）</p><p>如果想要撤銷對PPA的改變，使用 <code>ppa-purge</code> 命令。</p><p>有什麼意見，想法，或者指正，就在下面的評論欄裏寫下來吧。（我沒有 NVIDIA 的硬件來為我自己驗證上面的這些東西，如果你可以驗證的話，那就太感謝了。）</p><hr>`,21)),p("p",null,[t[4]||(t[4]=r("via: ",-1)),e(n,{href:"http://www.omgubuntu.co.uk/2015/08/ubuntu-nvidia-graphics-drivers-ppa-is-ready-for-action"},{default:o(()=>[...t[3]||(t[3]=[r("http://www.omgubuntu.co.uk/2015/08/ubuntu-nvidia-graphics-drivers-ppa-is-ready-for-action",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=r("作者：",-1)),e(n,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:o(()=>[...t[5]||(t[5]=[r("Joey-Elijah Sneddon",-1)])]),_:1}),t[9]||(t[9]=r(" 譯者：",-1)),e(n,{href:"https://github.com/DongShuaike"},{default:o(()=>[...t[6]||(t[6]=[r("DongShuaike",-1)])]),_:1}),t[10]||(t[10]=r(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[r("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=r("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[r("LCTT",-1)])]),_:1}),t[14]||(t[14]=r(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[r("Linux中國",-1)])]),_:1}),t[15]||(t[15]=r(" 榮譽推出",-1))])])}const N=i(l,[["render",P]]);export{v as __pageData,N as default};
